
/* ============================================================
   Interactions — Formation Alibaba & Pinduoduo
   ============================================================ */
(function () {
  "use strict";

  document.documentElement.classList.add("js");

  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------- Sticky header + scroll progress ---------- */
  const header = document.querySelector(".site-header");
  const progress = document.querySelector(".scroll-progress span");

  function onScroll() {
    const y = window.scrollY || window.pageYOffset || 0;
    if (header) header.classList.toggle("is-scrolled", y > 8);
    const max = document.documentElement.scrollHeight - window.innerHeight;
    if (progress) {
      const pct = max > 0 ? Math.min(100, (y / max) * 100) : 0;
      progress.style.width = pct + "%";
    }
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Scroll reveals ---------- */
  const reveals = document.querySelectorAll(".reveal");
  if (reduceMotion || !("IntersectionObserver" in window)) {
    reveals.forEach(function (el) { el.classList.add("in"); });
  } else {
    const revealObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("in");
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -36px 0px" });
    reveals.forEach(function (el) { revealObserver.observe(el); });
  }

  /* ---------- Animated counters ---------- */
  const counters = document.querySelectorAll("[data-count]");

  function runCounter(el) {
    const target = parseInt(el.getAttribute("data-count"), 10) || 0;
    const pad = parseInt(el.getAttribute("data-pad"), 10) || 0;

    if (reduceMotion) {
      el.textContent = String(target).padStart(pad, "0");
      return;
    }

    const duration = 1100;
    const start = performance.now();

    function tick(now) {
      const p = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - p, 3);
      el.textContent = String(Math.round(target * eased)).padStart(pad, "0");
      if (p < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  if (!("IntersectionObserver" in window)) {
    counters.forEach(runCounter);
  } else {
    const counterObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          runCounter(entry.target);
          counterObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.6 });
    counters.forEach(function (el) { counterObserver.observe(el); });
  }

  /* ---------- Hero visual: scale the fixed design canvas to fit ---------- */
  const stage = document.querySelector(".visual-stage");
  const visualBox = document.querySelector(".hero-visual");
  const STAGE_W = 574;
  const STAGE_H = 580;

  function fitStage() {
    if (!stage || !visualBox) return;
    stage.style.transformOrigin = "top left";
    const w = visualBox.clientWidth;
    if (!w) return;
    const scale = Math.max(0.3, w / STAGE_W);
    stage.style.width = STAGE_W + "px";
    stage.style.height = STAGE_H + "px";
    stage.style.transform = "scale(" + scale.toFixed(4) + ")";
    visualBox.style.minHeight = Math.round(STAGE_H * scale) + "px";

    /* Pinduoduo mini-site : rendering at 390px then scaled into the phone */
    const pddScreen = document.querySelector(".phone-screen");
    const pddMini = document.querySelector(".pdd-mini");
    if (pddScreen && pddMini && pddScreen.clientWidth) {
      const pddScale = pddScreen.clientWidth / 390;
      pddMini.style.transform = "scale(" + pddScale.toFixed(4) + ")";
    }
  }

  fitStage();
  window.addEventListener("resize", fitStage, { passive: true });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fitStage);

  /* ---------- Hero pointer parallax (desktop only) ---------- */
  const visual = document.querySelector(".hero-visual");
  const canHover = window.matchMedia("(hover: hover) and (pointer: fine)").matches;

  if (visual && !reduceMotion && canHover) {
    let raf = 0;

    visual.addEventListener("pointermove", function (e) {
      if (raf) return;
      raf = requestAnimationFrame(function () {
        const rect = visual.getBoundingClientRect();
        const x = (e.clientX - rect.left) / rect.width - 0.5;
        const y = (e.clientY - rect.top) / rect.height - 0.5;
        visual.style.setProperty("--mx", x.toFixed(3));
        visual.style.setProperty("--my", y.toFixed(3));
        raf = 0;
      });
    });

    visual.addEventListener("pointerleave", function () {
      visual.style.setProperty("--mx", 0);
      visual.style.setProperty("--my", 0);
    });
  }

  /* ---------- Active nav link ---------- */
  const sections = Array.prototype.slice.call(document.querySelectorAll("section[id]"));
  const navLinks = Array.prototype.slice.call(document.querySelectorAll('.nav a[href^="#"]'));

  if (sections.length && navLinks.length && "IntersectionObserver" in window) {
    const navObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        const id = "#" + entry.target.id;
        navLinks.forEach(function (link) {
          link.classList.toggle("is-active", link.getAttribute("href") === id);
        });
      });
    }, { rootMargin: "-45% 0px -50% 0px" });

    sections.forEach(function (section) { navObserver.observe(section); });
  }
})();

/* ============================================================
   Mini-site Alibaba interactif (dans l'ordinateur du hero)
   ============================================================ */
(function () {
  "use strict";

  const root = document.getElementById("aliMini");
  if (!root) return;

  /* Vrais articles : photos réelles récupérées sur la boutique Pinduoduo */
  const products = [
    { id: 1, cat: "apparel", name: "Women's Ribbed Henley Top", price: 3.90, moq: 100, supplier: "Yiwu Textile Factory", img: "data:image/jpeg;base64,", assured: true, tiers: "100 pcs: $3.90 · 500 pcs: $3.45 · 2000+: $2.95", desc: "Slim-fit ribbed cotton top with gold-tone buttons, mixed colours, sizes S–XL." },
    { id: 2, cat: "apparel", name: "Lightweight Puffer Jacket", price: 8.60, moq: 60, supplier: "Ningbo Apparel Co.", img: "data:image/jpeg;base64,", assured: true, tiers: "60 pcs: $8.60 · 300 pcs: $7.90", desc: "Women's padded puffer jacket with detachable fur hood, winter collection." },
    { id: 3, cat: "apparel", name: "Colourful Striped Knit Dress", price: 6.20, moq: 120, supplier: "Shantou Knitwear", img: "data:image/png;base64,", assured: false, tiers: "120 pcs: $6.20 · 600 pcs: $5.60", desc: "Long-sleeve rainbow striped knit dress, soft fabric, one size fits most." },
    { id: 4, cat: "beauty", name: "Rose Gold Pendant Necklace", price: 1.85, moq: 50, supplier: "Yiwu Jewelry Co.", img: "data:image/jpeg;base64,", assured: true, tiers: "50 pcs: $1.85 · 300 pcs: $1.55 · 1000+: $1.30", desc: "Fashion jewellery: rose-gold roman numeral circle pendant with crystal, gift boxed." },
    { id: 5, cat: "home", name: "Mung Bean Pastry Cakes — 500g", price: 0.95, moq: 500, supplier: "Foshan Food Trading", img: "data:image/jpeg;base64,", assured: false, tiers: "500 packs: $0.95 · 5000+: $0.78", desc: "Traditional Chinese pastry with flaky crust and mung bean filling, 500g pack." }
  ];

  const state = { cat: "all", q: "", sort: "relevance", assurance: false, cart: [] };
  const $ = function (s) { return root.querySelector(s); };
  const $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
  const money = function (n) { return n.toFixed(2).replace(".", ",") + " $"; };

  function visibleProducts() {
    let list = products.filter(function (p) {
      const catOk = state.cat === "all" || p.cat === state.cat;
      const qOk = !state.q || (p.name + " " + p.supplier + " " + p.cat).toLowerCase().indexOf(state.q) !== -1;
      const assOk = !state.assurance || p.assured;
      return catOk && qOk && assOk;
    });
    if (state.sort === "price-asc") list.sort(function (a, b) { return a.price - b.price; });
    if (state.sort === "price-desc") list.sort(function (a, b) { return b.price - a.price; });
    if (state.sort === "moq") list.sort(function (a, b) { return a.moq - b.moq; });
    return list;
  }

  function productCard(p) {
    return '<article class="mini-card" data-id="' + p.id + '" tabindex="0" role="button" aria-label="Voir ' + p.name + '">' +
      '<div class="mini-thumb"><img src="' + p.img + '" alt="' + p.name + '" loading="lazy"></div>' +
      '<div class="mini-price">' + money(p.price) + ' <small>/ pièce</small></div>' +
      '<div class="mini-title">' + p.name + '</div>' +
      '<div class="mini-meta"><span>MOQ ' + p.moq + '</span><span>' + p.supplier.split(" ")[0] + '</span></div>' +
      (p.assured ? '<span class="mini-badge">✓ Trade Assurance</span>' : "") +
      '</article>';
  }

  function syncActive() {
    $$("[data-cat]").forEach(function (el) {
      el.classList.toggle("is-active", el.getAttribute("data-cat") === state.cat);
    });
    const sel = $(".mini-cat-select");
    if (sel) sel.value = state.cat;
    const ass = $("#miniAssuranceBtn");
    if (ass) ass.classList.toggle("is-active", state.assurance);
  }

  function render() {
    const list = visibleProducts();
    $("#miniProducts").innerHTML = list.map(productCard).join("");
    $("#miniEmpty").hidden = list.length > 0;
    $("#miniCartCount").textContent = state.cart.reduce(function (a, c) { return a + c.qty; }, 0);
    $$(".mini-card").forEach(function (el) {
      el.addEventListener("click", function () { openDetail(parseInt(el.getAttribute("data-id"), 10)); });
      el.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openDetail(parseInt(el.getAttribute("data-id"), 10)); }
      });
    });
    syncActive();
  }

  let toastTimer = 0;
  function toast(msg) {
    const el = $("#miniToast");
    el.textContent = msg;
    el.classList.add("show");
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function () { el.classList.remove("show"); }, 2400);
  }

  function showPanel(html) {
    const overlay = $("#miniOverlay");
    overlay.innerHTML = html;
    overlay.hidden = false;
    overlay.querySelector(".mini-close").addEventListener("click", closePanel);
  }
  function closePanel() {
    const overlay = $("#miniOverlay");
    overlay.hidden = true;
    overlay.innerHTML = "";
  }

  function openDetail(id) {
    const p = products.find(function (x) { return x.id === id; });
    if (!p) return;
    showPanel(
      '<div class="mini-panel" role="dialog" aria-label="Fiche produit">' +
        '<div class="mini-panel-head"><b>Product details</b><button class="mini-close" type="button" aria-label="Fermer">×</button></div>' +
        '<div class="mini-panel-body">' +
          '<div class="mini-detail-thumb"><img src="' + p.img + '" alt="' + p.name + '"></div>' +
          '<div class="mini-detail-info">' +
            '<h4>' + p.name + '</h4>' +
            '<div class="mini-detail-price">' + money(p.price) + ' <small>/ piece · MOQ ' + p.moq + '</small></div>' +
            '<p>' + p.desc + '</p>' +
            '<p>Supplier: <b>' + p.supplier + '</b> · ' + (p.assured ? "Trade Assurance ✓" : "Standard supplier") + '</p>' +
            '<div class="mini-tiers">' + p.tiers.split(" · ").map(function (t) { return '<span class="mini-tier">' + t + '</span>'; }).join("") + '</div>' +
            '<button class="mini-primary-btn" type="button" data-add="' + p.id + '">Add to cart</button>' +
            '<button class="mini-ghost-btn" type="button" data-inquiry="' + p.id + '">Send inquiry</button>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
    $("#miniOverlay [data-add]").addEventListener("click", function () {
      const item = state.cart.find(function (c) { return c.id === p.id; });
      if (item) item.qty += 1; else state.cart.push({ id: p.id, qty: 1 });
      render();
      toast(p.name + " ajouté au panier");
      closePanel();
    });
    $("#miniOverlay [data-inquiry]").addEventListener("click", function () {
      toast("Demande envoyée à " + p.supplier + " (démo)");
      closePanel();
    });
  }

  function openCart() {
    const items = state.cart.map(function (c) {
      const p = products.find(function (x) { return x.id === c.id; });
      return { p: p, qty: c.qty };
    });
    const total = items.reduce(function (a, it) { return a + it.p.price * it.qty; }, 0);
    showPanel(
      '<div class="mini-panel" role="dialog" aria-label="Panier">' +
        '<div class="mini-panel-head"><b>Shopping cart (' + items.reduce(function (a, i) { return a + i.qty; }, 0) + ')</b><button class="mini-close" type="button" aria-label="Fermer">×</button></div>' +
        '<div class="mini-panel-body" style="display:block">' +
          (items.length ? items.map(function (it) {
            return '<div class="mini-cart-item">' +
              '<div class="mini-thumb"><img src="' + it.p.img + '" alt=""></div>' +
              '<div><b>' + it.p.name + '</b><span>' + money(it.p.price) + ' × ' + it.qty + '</span></div>' +
              '<button class="mini-ghost-btn" type="button" data-remove="' + it.p.id + '">Remove</button>' +
            '</div>';
          }).join("") : '<p style="font-size:12px;color:#888">Votre panier est vide. Cliquez sur un produit pour l’ajouter.</p>') +
          '<div class="mini-cart-foot"><b>Total: <span>' + money(total) + '</span></b>' +
            '<button class="mini-primary-btn" type="button" id="miniCheckout">Send inquiry (démo)</button></div>' +
        '</div>' +
      '</div>'
    );
    $$("#miniOverlay [data-remove]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        const id = parseInt(btn.getAttribute("data-remove"), 10);
        state.cart = state.cart.filter(function (c) { return c.id !== id; });
        render();
        openCart();
      });
    });
    const checkout = $("#miniCheckout");
    if (checkout) checkout.addEventListener("click", function () { toast("Demande envoyée — l'équipe vous répond sur WhatsApp"); closePanel(); });
  }

  /* Events */
  $(".mini-search-btn").addEventListener("click", function () {
    state.q = $(".mini-search-input").value.trim().toLowerCase();
    render();
  });
  $(".mini-search-input").addEventListener("keydown", function (e) {
    if (e.key === "Enter") { e.preventDefault(); $(".mini-search-btn").click(); }
  });
  $(".mini-cat-select").addEventListener("change", function (e) { state.cat = e.target.value; render(); });
  $("#miniSort").addEventListener("change", function (e) { state.sort = e.target.value; render(); });
  $("#miniCartBtn").addEventListener("click", openCart);
  $("#miniAssuranceBtn").addEventListener("click", function () { state.assurance = !state.assurance; render(); });
  $$("[data-cat]").forEach(function (el) {
    el.addEventListener("click", function () { state.cat = el.getAttribute("data-cat"); render(); });
  });
  $("#miniOverlay").addEventListener("click", function (e) {
    if (e.target === $("#miniOverlay")) closePanel();
  });

  render();
})();

/* ============================================================
   Mini-site Pinduoduo interactif (dans le téléphone du hero)
   ============================================================ */
(function () {
  "use strict";

  const root = document.getElementById("pddMini");
  if (!root) return;

  const products = [
    { id: 1, cat: "apparel", name: "Ensemble sweat capuche + jogging vintage", price: 35.09, old: 49.09, group: 12842, img: "data:image/jpeg;base64," },
    { id: 2, cat: "apparel", name: "Doudoune légère à capuche fourrure", price: 58.90, old: 89.00, group: 8931, img: "data:image/jpeg;base64," },
    { id: 3, cat: "apparel", name: "Robe tricotée rayée colorée", price: 42.50, old: 69.00, group: 5210, img: "data:image/png;base64," },
    { id: 4, cat: "beauty", name: "Collier pendentif or rose chiffres romains", price: 12.90, old: 25.00, group: 20418, img: "data:image/jpeg;base64," },
    { id: 5, cat: "home", name: "Gâteaux aux haricots mungo — 500 g", price: 9.90, old: 18.00, group: 15670, img: "data:image/jpeg;base64," }
  ];

  const state = { cat: "all", q: "", cart: [] };
  const $ = function (s) { return root.querySelector(s); };
  const $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
  const yuan = function (n) { return "¥" + n.toFixed(2); };

  function visible() {
    return products.filter(function (p) {
      return (state.cat === "all" || p.cat === state.cat) &&
        (!state.q || (p.name + " " + p.cat).toLowerCase().indexOf(state.q) !== -1);
    });
  }

  function render() {
    const list = visible();
    $("#pmProducts").innerHTML = list.map(function (p) {
      return '<article class="pm-card" data-id="' + p.id + '" tabindex="0" role="button" aria-label="Voir ' + p.name + '">' +
        '<img src="' + p.img + '" alt="' + p.name + '" loading="lazy">' +
        '<div class="pm-card-body">' +
          '<div class="pm-card-title">' + p.name + '</div>' +
          '<div class="pm-card-price">' + yuan(p.price) + '<small>' + yuan(p.old) + '</small><s>' + Math.round((1 - p.price / p.old) * 100) + '% off</s></div>' +
          '<span class="pm-card-group">' + p.group.toLocaleString("fr-FR") + ' achètent ensemble</span>' +
        '</div></article>';
    }).join("");
    $("#pmEmpty").hidden = list.length > 0;
    $("#pmCartCount").textContent = state.cart.reduce(function (a, c) { return a + c.qty; }, 0);
    $$(".pm-card").forEach(function (el) {
      el.addEventListener("click", function () { openProduct(parseInt(el.getAttribute("data-id"), 10)); });
      el.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openProduct(parseInt(el.getAttribute("data-id"), 10)); }
      });
    });
    $$("#pmTabs button").forEach(function (b) {
      b.classList.toggle("is-active", b.getAttribute("data-cat") === state.cat);
    });
  }

  let toastTimer = 0;
  function toast(msg) {
    const el = $("#pmToast");
    el.textContent = msg;
    el.classList.add("show");
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function () { el.classList.remove("show"); }, 2200);
  }

  function sheet(html) {
    const o = $("#pmOverlay");
    o.innerHTML = '<div class="pm-sheet" role="dialog">' + html + '</div>';
    o.hidden = false;
    o.querySelector(".pm-close").addEventListener("click", closeSheet);
  }
  function closeSheet() {
    const o = $("#pmOverlay");
    o.hidden = true;
    o.innerHTML = "";
  }

  function addToCart(id) {
    const item = state.cart.find(function (c) { return c.id === id; });
    if (item) item.qty += 1; else state.cart.push({ id: id, qty: 1 });
    render();
    closeSheet();
    toast("Ajouté au panier — achat groupé disponible");
  }

  function openProduct(id) {
    const p = products.find(function (x) { return x.id === id; });
    if (!p) return;
    sheet(
      '<div class="pm-sheet-head"><b>Achat groupé</b><button class="pm-close" type="button" aria-label="Fermer">×</button></div>' +
      '<div class="pm-sheet-body">' +
        '<img src="' + p.img + '" alt="' + p.name + '">' +
        '<div class="pm-sheet-info">' +
          '<h4>' + p.name + '</h4>' +
          '<div class="pm-sheet-price">' + yuan(p.price) + '<s>' + yuan(p.old) + '</s></div>' +
          '<p>' + p.group.toLocaleString("fr-FR") + ' personnes achètent ensemble · livraison gratuite</p>' +
          '<button class="pm-btn group" type="button" data-add="' + p.id + '">Achat groupé ' + yuan(p.price) + '</button>' +
          '<button class="pm-btn solo" type="button" data-add="' + p.id + '">Acheter seul ' + yuan(p.price + 8) + '</button>' +
        '</div>' +
      '</div>'
    );
    $$("#pmOverlay [data-add]").forEach(function (b) {
      b.addEventListener("click", function () { addToCart(parseInt(b.getAttribute("data-add"), 10)); });
    });
  }

  function openCart() {
    const items = state.cart.map(function (c) {
      return { p: products.find(function (x) { return x.id === c.id; }), qty: c.qty };
    });
    const total = items.reduce(function (a, it) { return a + it.p.price * it.qty; }, 0);
    sheet(
      '<div class="pm-sheet-head"><b>Panier (' + items.reduce(function (a, i) { return a + i.qty; }, 0) + ')</b><button class="pm-close" type="button" aria-label="Fermer">×</button></div>' +
      '<div style="padding:6px 14px">' +
        (items.length ? items.map(function (it) {
          return '<div class="pm-cart-item">' +
            '<img src="' + it.p.img + '" alt="">' +
            '<div><b>' + it.p.name + '</b><span>' + yuan(it.p.price) + ' × ' + it.qty + '</span></div>' +
            '<button class="pm-remove" type="button" data-remove="' + it.p.id + '">Retirer</button></div>';
        }).join("") : '<p style="font-size:12px;color:#999;padding:14px 0">Panier vide. Touchez un produit pour l’ajouter.</p>') +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 0">' +
          '<b style="font-size:16px">Total : <span style="color:#E22B1F">' + yuan(total) + '</span></b>' +
          '<button class="pm-btn group" style="width:auto;padding:10px 18px;margin:0" type="button" id="pmCheckout">Passer commande</button>' +
        '</div>' +
      '</div>'
    );
    $$("#pmOverlay [data-remove]").forEach(function (b) {
      b.addEventListener("click", function () {
        const id = parseInt(b.getAttribute("data-remove"), 10);
        state.cart = state.cart.filter(function (c) { return c.id !== id; });
        render();
        openCart();
      });
    });
    const co = $("#pmCheckout");
    if (co) co.addEventListener("click", function () { toast("Commande simulée — contactez-nous sur WhatsApp"); closeSheet(); });
  }

  /* Events */
  $(".pm-search-btn").addEventListener("click", function () {
    state.q = $(".pm-search-input").value.trim().toLowerCase();
    render();
  });
  $(".pm-search-input").addEventListener("keydown", function (e) {
    if (e.key === "Enter") { e.preventDefault(); $(".pm-search-btn").click(); }
  });
  $$("#pmTabs button").forEach(function (b) {
    b.addEventListener("click", function () { state.cat = b.getAttribute("data-cat"); render(); });
  });
  $$(".pm-nav button").forEach(function (b) {
    b.addEventListener("click", function () {
      const nav = b.getAttribute("data-nav");
      $$(".pm-nav button").forEach(function (x) { x.classList.toggle("is-active", x === b); });
      if (nav === "home") { state.cat = "all"; state.q = ""; $(".pm-search-input").value = ""; render(); }
      if (nav === "cat") { toast("Catégories : Vêtements · Bijoux · Alimentation"); }
      if (nav === "cart") openCart();
      if (nav === "me") toast("Profil Pinduoduo —connectez-vous pour synchroniser vos favoris");
    });
  });
  $("#pmOverlay").addEventListener("click", function (e) {
    if (e.target === $("#pmOverlay")) closeSheet();
  });

  render();
})();
